validator:
function validate(input) {
  const [{ Purchases = [], Users = [] }] = input;
  const users = new Set(), seen = new Set();
  for (const [id, membership] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    users.add(id);
    if (!['Standard', 'Premium', 'VIP'].includes(membership)) return `membership must be Standard, Premium or VIP (user ${id}).`;
  }
  for (const [user, date, amount] of Purchases) {
    if (user === null || date === null || amount === null) return 'Every purchase needs a user_id, a purchase_date and an amount_spend.';
    if (!users.has(user)) return `Purchase by user ${user}, who is not in Users.`;
    if (!/^2023-11-(0[1-9]|[12]\d|30)$/.test(date)) return `purchase_date ${date} is not in November 2023.`;
    if (amount <= 0) return 'amount_spend must be positive.';
    const key = `${user}|${date}|${amount}`;
    if (seen.has(key)) return `(${user}, ${date}, ${amount}) appears twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const tiers = ['Standard', 'Premium', 'VIP'];
  const userCount = small ? Math.floor(rand() * 7) : 500;
  const Users = [];
  for (let id = 1; id <= userCount; id++) Users.push([id, pick(tiers)]);
  const Purchases = [], seen = new Set();
  // Small cases lean on Fridays and their neighbours; large ones spread over the whole month.
  const days = [1, 2, 3, 3, 4, 9, 10, 10, 16, 17, 17, 18, 23, 24, 24, 25, 30];
  const target = userCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  for (let tries = 0; Purchases.length < target && tries < target * 5; tries++) {
    const user = 1 + Math.floor(rand() * userCount);
    const day = small ? pick(days) : 1 + Math.floor(rand() * 30);
    const amount = small ? pick([100, 250, 500, 1000]) : 1 + Math.floor(rand() * 10000);
    const date = `2023-11-${String(day).padStart(2, '0')}`, key = `${user}|${date}|${amount}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Purchases.push([user, date, amount]);
  }
  return [{ Purchases, Users }];
}
